const AMULET_BASE_PRICE = 60;
const SWORD_BASE_PRICE = 100;

const basePrice = (item: Item): number =>
  item.type === "amulet" ? AMULET_BASE_PRICE : SWORD_BASE_PRICE;

// The premium is base × 1.1 (first-insurance surcharge) + 5 G fee, but that
// arithmetic is left inlined until the rounding test pins down the direction:
// 100 × 1.1 + 5 is 115.00000000000001 in floating point, not 115.
const quotePremium = (item: Item): number =>
  basePrice(item) === AMULET_BASE_PRICE ? 71 : 115;

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const item = scenario.steps[0].items![0];
  return { results: [{ premium: quotePremium(item) }] };
};

